 void add(){final n=TextEditingController(),d=TextEditingController(),des=TextEditingController(),p=TextEditingController(),e=TextEditingController();showDialog(context:context,builder:(_)=>AlertDialog(title:const Text('Add Employee'),content:SingleChildScrollView(child:Column(children:[TextField(controller:n,decoration:const InputDecoration(labelText:'Full Name *')),TextField(controller:d,decoration:const InputDecoration(labelText:'Department')),TextField(controller:des,decoration:const InputDecoration(labelText:'Designation')),TextField(controller:p,keyboardType:TextInputType.phone,decoration:const InputDecoration(labelText:'Phone')),TextField(controller:e,decoration:const InputDecoration(labelText:'Email'))])),actions:[TextButton(onPressed:()=>Navigator.pop(context),child:const Text('Cancel')),FilledButton(onPressed:(){if(n.text.trim().isEmpty)return;final id='EMP${(service.employees.length+1).toString().padLeft(3,'0')}';service.addEmployee(Employee(id:id,name:n.text.trim(),department:d.text.trim(),designation:des.text.trim().isEmpty?'Employee':des.text.trim(),manager:'HR Admin',joiningDate:DateTime.now(),employmentType:'Full Time',status:'Active',phone:p.text.trim(),email:e.text.trim()));Navigator.pop(context);setState((){});},child:const Text('Save'))]));}
 @override Widget build(BuildContext context)=>ListView(padding:const EdgeInsets.all(16),children:[Row(children:[const Expanded(child:Text('Employee Management',style:TextStyle(fontSize:28,fontWeight:FontWeight.w800))),FilledButton.icon(onPressed:add,icon:const Icon(Icons.add),label:const Text('Add'))]),const SizedBox(height:16),...service.employees.map((e)=>Card(child:ListTile(leading:CircleAvatar(child:Text(e.name[0])),title:Text(e.name,style:const TextStyle(fontWeight:FontWeight.w700)),subtitle:Text('${e.id} • ${e.department}\n${e.designation} • ${e.phone}\n${e.email}'),isThreeLine:true,trailing:PopupMenuButton<String>(onSelected:(v){if(v=='delete'){service.removeEmployee(e.id);setState((){});}},itemBuilder:(_)=>const[PopupMenuItem(value:'delete',child:Text('Delete'))]))))]);
