class AttendanceScreen extends StatefulWidget { final HrmsService service; const AttendanceScreen({super.key,required this.service}); @override State<AttendanceScreen> createState()=>_AttendanceScreenState(); }
class _AttendanceScreenState extends State<AttendanceScreen>{ String employee='EMP001'; @override Widget build(BuildContext context){if(!service.employees.any((e)=>e.id==employee))employee=service.employees.first.id;final r=service.todayFor(employee);return ListView(padding:const EdgeInsets.all(16),children:[const Text('Attendance',style:TextStyle(fontSize:28,fontWeight:FontWeight.w800)),const SizedBox(height:16),DropdownButtonFormField<String>(value:employee,decoration:const InputDecoration(labelText:'Employee',border:OutlineInputBorder()),items:service.employees.map((e)=>DropdownMenuItem(value:e.id,child:Text('${e.name} (${e.id})'))).toList(),onChanged:(v)=>setState(()=>employee=v!)),const SizedBox(height:16),Card(child:Padding(padding:const EdgeInsets.all(18),child:Column(children:[Text(r?.punchIn==null?'Not punched in':'Punched in: ${_time(r!.punchIn!)}',style:const TextStyle(fontSize:18,fontWeight:FontWeight.w700)),if(r?.punchOut!=null)Text('Punched out: ${_time(r!.punchOut!)}'),const SizedBox(height:16),Row(children:[Expanded(child:FilledButton.icon(onPressed:r?.punchIn==null?(){service.punchIn(employee);setState((){});}:null,icon:const Icon(Icons.login),label:const Text('Punch In'))),const SizedBox(width:10),Expanded(child:OutlinedButton.icon(onPressed:r?.punchIn!=null&&r?.punchOut==null?(){service.punchOut(employee);setState((){});}:null,icon:const Icon(Icons.logout),label:const Text('Punch Out')))]),if(r!=null)Padding(padding:const EdgeInsets.only(top:12),child:Text('Status: ${r.status} • Working ${r.workingTime.inHours}h ${r.workingTime.inMinutes%60}m • OT ${r.overtime.inHours}h ${r.overtime.inMinutes%60}m'))])),const SizedBox(height:12),Card(child:ListTile(title:const Text('Attendance History'),subtitle:Text('${service.attendance.length} attendance record(s)')))]);}
 String _time(DateTime d)=>'${d.hour.toString().padLeft(2,'0')}:${d.minute.toString().padLeft(2,'0')}';
}

class LeaveScreen extends StatefulWidget { final HrmsService service; const LeaveScreen({super.key,required this.service}); @override State<LeaveScreen> createState()=>_LeaveScreenState(); }
class _LeaveScreenState extends State<LeaveScreen>{
 void apply(){String emp=service.employees.first.id,type='Casual Leave';DateTime from=DateTime.now(),to=DateTime.now();final reason=TextEditingController();showDialog(context:context,builder:(_)=>StatefulBuilder(builder:(c,set)=>AlertDialog(title:const Text('Apply Leave'),content:SingleChildScrollView(child:Column(children:[DropdownButtonFormField<String>(value:emp,decoration:const InputDecoration(labelText:'Employee'),items:service.employees.map((e)=>DropdownMenuItem(value:e.id,child:Text(e.name))).toList(),onChanged:(v)=>set(()=>emp=v!)),DropdownButtonFormField<String>(value:type,decoration:const InputDecoration(labelText:'Leave Type'),items:const['Casual Leave','Sick Leave','Earned Leave','Unpaid Leave'].map((x)=>DropdownMenuItem(value:x,child:Text(x))).toList(),onChanged:(v)=>set(()=>type=v!)),ListTile(leading:const Icon(Icons.date_range),title:Text('From ${from.day}/${from.month}/${from.year}'),onTap:()async{final x=await showDatePicker(context:c,firstDate:DateTime.now(),lastDate:DateTime.now().add(const Duration(days:365)),initialDate:from);if(x!=null)set(()=>from=x);}),ListTile(leading:const Icon(Icons.event),title:Text('To ${to.day}/${to.month}/${to.year}'),onTap:()async{final x=await showDatePicker(context:c,firstDate:from,lastDate:DateTime.now().add(const Duration(days:365)),initialDate:to.isBefore(from)?from:to);if(x!=null)set(()=>to=x);}),TextField(controller:reason,decoration:const InputDecoration(labelText:'Reason',border:OutlineInputBorder()),maxLines:2)])),actions:[TextButton(onPressed:()=>Navigator.pop(c),child:const Text('Cancel')),FilledButton(onPressed:(){if(reason.text.trim().isEmpty||to.isBefore(from))return;service.applyLeave(LeaveRequest(id:'L${service.leaves.length+1}',employeeId:emp,type:type,from:from,to:to,reason:reason.text.trim()));Navigator.pop(c);setState((){});},child:const Text('Submit'))]));}
 @override Widget build(BuildContext context)=>ListView(padding:const EdgeInsets.all(16),children:[Row(children:[const Expanded(child:Text('Leave Management',style:TextStyle(fontSize:28,fontWeight:FontWeight.w800))),FilledButton.icon(onPressed:apply,icon:const Icon(Icons.add),label:const Text('Apply'))]),const SizedBox(height:16),...service.employees.map((e)=>Card(child:ListTile(title:Text(e.name),subtitle:Text('Balance: ${service.leaveBalances[e.id]??0} days • Requests: ${service.leaves.where((l)=>l.employeeId==e.id).length}')))),const SizedBox(height:8),...service.leaves.map((l)=>Card(child:ListTile(title:Text('${l.type} • ${l.days} day(s)'),subtitle:Text('${l.employeeId} • ${l.reason}'),trailing:Chip(label:Text(l.status)),onTap:()=>showDialog(context:context,builder:(_)=>AlertDialog(title:Text(l.type),content:Text('Status: ${l.status}\n${l.from.day}/${l.from.month}/${l.from.year} → ${l.to.day}/${l.to.month}/${l.to.year}\nReason: ${l.reason}'),actions:[if(l.status=='Pending')TextButton(onPressed:(){service.decideLeave(l.id,false);Navigator.pop(context);setState((){});},child:const Text('Reject')),if(l.status=='Pending')FilledButton(onPressed:(){service.decideLeave(l.id,true);Navigator.pop(context);setState((){});},child:const Text('Approve')),TextButton(onPressed:()=>Navigator.pop(context),child:const Text('Close'))]))))];
}

